	return ctx.Err()
}

// Stop shuts the runner down, waiting up to 30 seconds for running jobs. See Shutdown.
func (r *Runner) Stop() {
	ctx, cancel := context.WithTimeout(context.Background(), stopTimeout)
	defer cancel()
	_ = r.Shutdown(ctx)
}

// Pending returns the jobs that still need to run, in enqueue order. Before Shutdown these are the
