package jobs

import (
	"context"
	"errors"
	"runtime"
	"sync"
	"testing"
	"time"
)

func TestRunnerRunsJobs(t *testing.T) {
	r := NewRunner(3, 10, nil)
	r.Start()
	var mu sync.Mutex
	done := map[string]bool{}
	var wg sync.WaitGroup
	for _, name := range []string{"a", "b", "c", "d", "e"} {
		wg.Add(1)
		if err := r.Enqueue(Job{Name: name, Run: func(ctx context.Context) error {
			defer wg.Done()
			mu.Lock()
			done[name] = true
			mu.Unlock()
			return nil
		}}); err != nil {
			t.Fatal(err)
		}
	}
	finished := make(chan struct{})
	go func() { wg.Wait(); close(finished) }()
	select {
	case <-finished:
	case <-time.After(5 * time.Second):
		t.Fatal("jobs did not run")
	}
	if len(done) != 5 {
		t.Fatalf("done = %v", done)
	}
}

func TestEnqueueWhenFull(t *testing.T) {
	r := NewRunner(1, 1, nil) // not started: nothing takes jobs off the queue
	job := Job{Name: "x", Run: func(context.Context) error { return nil }}
	if err := r.Enqueue(job); err != nil {
		t.Fatal(err)
	}
	if err := r.Enqueue(job); !errors.Is(err, ErrQueueFull) {
		t.Fatalf("err = %v, want ErrQueueFull", err)
	}
}

// blocker returns a job that signals started and then runs until its context is cancelled.
// It returns the job's context error and records that it saw the cancellation in cancelled.
func blocker(name string, started chan<- struct{}, cancelled *bool) Job {
	return Job{Name: name, Run: func(ctx context.Context) error {
		started <- struct{}{}
		<-ctx.Done()
		*cancelled = true
		return ctx.Err()
	}}
}

func names(jobs []Job) []string {
	out := make([]string, 0, len(jobs))
	for _, j := range jobs {
		out = append(out, j.Name)
	}
	return out
}

func equalNames(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func TestEnqueueAfterShutdownReturnsErrStopped(t *testing.T) {
	r := NewRunner(1, 10, nil)
	r.Start()
	if err := r.Shutdown(context.Background()); err != nil {
		t.Fatal(err)
	}
	job := Job{Name: "late", Run: func(context.Context) error { return nil }}
	if err := r.Enqueue(job); !errors.Is(err, ErrStopped) {
		t.Fatalf("err = %v, want ErrStopped", err)
	}
	if got := names(r.Pending()); len(got) != 0 {
		t.Fatalf("pending = %v, want none", got)
	}
}

func TestShutdownWaitsForRunningJobs(t *testing.T) {
	r := NewRunner(1, 10, nil)
	r.Start()
	finished := false
	if err := r.Enqueue(Job{Name: "slow", Run: func(context.Context) error {
		time.Sleep(50 * time.Millisecond)
		finished = true
		return nil
	}}); err != nil {
		t.Fatal(err)
	}
	time.Sleep(10 * time.Millisecond) // let the worker pick the job up
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	if err := r.Shutdown(ctx); err != nil {
		t.Fatalf("Shutdown = %v, want nil", err)
	}
	if !finished {
		t.Fatal("Shutdown returned before the running job finished")
	}
	if got := names(r.Pending()); len(got) != 0 {
		t.Fatalf("pending = %v, want none", got)
	}
}

func TestShutdownCancelsRunningJobsWhenContextEnds(t *testing.T) {
	r := NewRunner(1, 10, nil)
	r.Start()
	started := make(chan struct{}, 1)
	var cancelled bool
	if err := r.Enqueue(blocker("running", started, &cancelled)); err != nil {
		t.Fatal(err)
	}
	<-started
	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Millisecond)
	defer cancel()
	if err := r.Shutdown(ctx); !errors.Is(err, context.DeadlineExceeded) {
		t.Fatalf("Shutdown = %v, want context.DeadlineExceeded", err)
	}
	if !cancelled {
		t.Fatal("running job's context was not cancelled")
	}
	if got := names(r.Pending()); !equalNames(got, []string{"running"}) {
		t.Fatalf("pending = %v, want [running]", got)
	}
}

func TestShutdownDoesNotStartQueuedJobs(t *testing.T) {
	r := NewRunner(1, 10, nil) // one worker, so the other jobs wait in the queue
	r.Start()
	started := make(chan struct{}, 1)
	var cancelled bool
	var ran []string
	var mu sync.Mutex
	record := func(name string) Job {
		return Job{Name: name, Run: func(context.Context) error {
			mu.Lock()
			ran = append(ran, name)
			mu.Unlock()
			return nil
		}}
	}
	if err := r.Enqueue(blocker("first", started, &cancelled)); err != nil {
		t.Fatal(err)
	}
	<-started
	for _, name := range []string{"second", "third"} {
		if err := r.Enqueue(record(name)); err != nil {
			t.Fatal(err)
		}
	}
	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Millisecond)
	defer cancel()
	if err := r.Shutdown(ctx); !errors.Is(err, context.DeadlineExceeded) {
		t.Fatalf("Shutdown = %v, want context.DeadlineExceeded", err)
	}
	mu.Lock()
	defer mu.Unlock()
	if len(ran) != 0 {
		t.Fatalf("queued jobs ran: %v", ran)
	}
	// Never-started jobs come first, then the canceled job.
	if got := names(r.Pending()); !equalNames(got, []string{"second", "third", "first"}) {
		t.Fatalf("pending = %v, want [second third first]", got)
	}
}

func TestCanceledJobThatSucceedsIsNotPending(t *testing.T) {
	r := NewRunner(1, 10, nil)
	r.Start()
	started := make(chan struct{}, 1)
	if err := r.Enqueue(Job{Name: "graceful", Run: func(ctx context.Context) error {
		started <- struct{}{}
		<-ctx.Done()
		return nil
	}}); err != nil {
		t.Fatal(err)
	}
	<-started
	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Millisecond)
	defer cancel()
	if err := r.Shutdown(ctx); !errors.Is(err, context.DeadlineExceeded) {
		t.Fatalf("Shutdown = %v, want context.DeadlineExceeded", err)
	}
	if got := names(r.Pending()); len(got) != 0 {
		t.Fatalf("pending = %v, want none", got)
	}
}

func TestPendingBeforeShutdownListsQueuedJobsInOrder(t *testing.T) {
	r := NewRunner(1, 10, nil) // not started: everything stays queued
	for _, name := range []string{"a", "b", "c"} {
		if err := r.Enqueue(Job{Name: name, Run: func(context.Context) error { return nil }}); err != nil {
			t.Fatal(err)
		}
	}
	if got := names(r.Pending()); !equalNames(got, []string{"a", "b", "c"}) {
		t.Fatalf("pending = %v, want [a b c]", got)
	}
}

func TestPanickingJobIsRecovered(t *testing.T) {
	r := NewRunner(1, 10, nil)
	r.Start()
	var mu sync.Mutex
	runs := map[string]int{}
	after := make(chan struct{})
	jobs := []Job{
		{Name: "boom", Run: func(context.Context) error {
			mu.Lock()
			runs["boom"]++
			mu.Unlock()
			panic("boom")
		}},
		{Name: "after", Run: func(context.Context) error {
			mu.Lock()
			runs["after"]++
			mu.Unlock()
			close(after)
			return nil
		}},
	}
	for _, j := range jobs {
		if err := r.Enqueue(j); err != nil {
			t.Fatal(err)
		}
	}
	select {
	case <-after:
	case <-time.After(5 * time.Second):
		t.Fatal("job after the panic did not run")
	}
	if err := r.Shutdown(context.Background()); err != nil {
		t.Fatal(err)
	}
	mu.Lock()
	defer mu.Unlock()
	if runs["boom"] != 1 || runs["after"] != 1 {
		t.Fatalf("runs = %v, want boom once and after once", runs)
	}
	if got := names(r.Pending()); len(got) != 0 {
		t.Fatalf("pending = %v, want none (a panicked job is not run again)", got)
	}
}

func TestSecondShutdownAndStopReturnAtOnce(t *testing.T) {
	r := NewRunner(2, 10, nil)
	r.Start()
	if err := r.Shutdown(context.Background()); err != nil {
		t.Fatal(err)
	}
	finished := make(chan struct{})
	go func() {
		if err := r.Shutdown(context.Background()); err != nil {
			t.Errorf("second Shutdown = %v, want nil", err)
		}
		r.Stop()
		close(finished)
	}()
	select {
	case <-finished:
	case <-time.After(5 * time.Second):
		t.Fatal("second Shutdown or Stop did not return")
	}
}

func TestStopWaitsForRunningJobs(t *testing.T) {
	r := NewRunner(1, 10, nil)
	r.Start()
	finished := false
	if err := r.Enqueue(Job{Name: "slow", Run: func(context.Context) error {
		time.Sleep(20 * time.Millisecond)
		finished = true
		return nil
	}}); err != nil {
		t.Fatal(err)
	}
	time.Sleep(5 * time.Millisecond)
	r.Stop()
	if !finished {
		t.Fatal("Stop returned before the running job finished")
	}
}

func TestShutdownLeavesNoGoroutines(t *testing.T) {
	before := runtime.NumGoroutine()
	r := NewRunner(4, 10, nil)
	r.Start()
	started := make(chan struct{}, 1)
	var cancelled bool
	if err := r.Enqueue(blocker("running", started, &cancelled)); err != nil {
		t.Fatal(err)
	}
	<-started
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Millisecond)
	defer cancel()
	_ = r.Shutdown(ctx)

	// Goroutines exit asynchronously after their last statement, so poll briefly.
	deadline := time.Now().Add(2 * time.Second)
	for runtime.NumGoroutine() > before {
		if time.Now().After(deadline) {
			t.Fatalf("goroutines = %d, want at most %d", runtime.NumGoroutine(), before)
		}
		time.Sleep(time.Millisecond)
	}
}

