// Package jobs runs background work (renewals, webhook deliveries, emails) on a fixed number of workers.
package jobs

import (
	"context"
	"errors"
	"io"
	"log/slog"
	"runtime/debug"
	"sort"
	"sync"
	"time"
)

// Job is one piece of background work.
type Job struct {
	Name string
	Run  func(ctx context.Context) error
}

// ErrQueueFull is returned by Enqueue when the queue has no room.
var ErrQueueFull = errors.New("the job queue is full")

// ErrStopped is returned by Enqueue once Shutdown or Stop has been called.
var ErrStopped = errors.New("the job runner is stopped")

// stopTimeout is how long Stop waits for running jobs before cancelling them.
const stopTimeout = 30 * time.Second

// entry is a job with the order it was enqueued in.
type entry struct {
	seq uint64
	job Job
}

// active is a job that a worker is running.
type active struct {
	cancel   context.CancelFunc
	canceled bool // set when Shutdown cancels the job's context
}

// Runner runs jobs on its workers.
type Runner struct {
	workers  int
	capacity int
	log      *slog.Logger

	// mu guards every field below it.
	mu   sync.Mutex
	cond *sync.Cond
	// queue holds the waiting jobs in enqueue order.
	queue []entry
	// seq is the sequence number of the last enqueued job.
	seq uint64
	// running holds the jobs that workers are running now.
	running map[*active]struct{}
	// failed holds jobs that Shutdown canceled and that then returned an error.
	failed []entry
	// stopping is set once Shutdown has been called.
	stopping bool
	// wg counts the worker goroutines.
	wg sync.WaitGroup
	// done is closed when the first Shutdown has finished.
	done chan struct{}
}

// NewRunner returns a runner with workers workers and room for queueSize waiting jobs. A nil log discards.
func NewRunner(workers, queueSize int, log *slog.Logger) *Runner {
	if workers < 1 {
		workers = 1
	}
	if queueSize < 0 {
		queueSize = 0
	}
	if log == nil {
		log = slog.New(slog.NewTextHandler(io.Discard, nil))
	}
	r := &Runner{
		workers:  workers,
		capacity: queueSize,
		log:      log,
		running:  map[*active]struct{}{},
		done:     make(chan struct{}),
	}
	r.cond = sync.NewCond(&r.mu)
	return r
}

// Start starts the workers. It does nothing once the runner is stopping.
func (r *Runner) Start() {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.stopping {
		return
	}
	for i := 0; i < r.workers; i++ {
		r.wg.Add(1)
		go r.work()
	}
}

func (r *Runner) work() {
	defer r.wg.Done()
	for {
		r.mu.Lock()
		for len(r.queue) == 0 && !r.stopping {
			r.cond.Wait()
		}
		if r.stopping {
			// Jobs still in the queue are never started; Pending returns them.
			r.mu.Unlock()
			return
		}
		e := r.queue[0]
		r.queue = r.queue[1:]
		ctx, cancel := context.WithCancel(context.Background())
		a := &active{cancel: cancel}
		r.running[a] = struct{}{}
		r.mu.Unlock()

		err := r.run(ctx, e.job)
		cancel()

		r.mu.Lock()
		delete(r.running, a)
		if a.canceled && err != nil {
			r.failed = append(r.failed, e)
		}
		r.mu.Unlock()
		if err != nil {
			r.log.Error("job failed", "job", e.job.Name, "err", err)
		}
	}
}

// run runs j and recovers a panic, so that one bad job does not stop the worker or the process.
func (r *Runner) run(ctx context.Context, j Job) (err error) {
	defer func() {
		if p := recover(); p != nil {
			r.log.Error("job panicked", "job", j.Name, "panic", p, "stack", string(debug.Stack()))
			err = nil
		}
	}()
	return j.Run(ctx)
}

// Enqueue adds a job to the queue without waiting. It returns ErrQueueFull when the queue has no room
// and ErrStopped once Shutdown has been called.
func (r *Runner) Enqueue(j Job) error {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.stopping {
		return ErrStopped
	}
	if len(r.queue) >= r.capacity {
		return ErrQueueFull
	}
	r.seq++
	r.queue = append(r.queue, entry{seq: r.seq, job: j})
	r.cond.Signal()
	return nil
}

// Shutdown stops the runner. Enqueue returns ErrStopped from now on and jobs that have not started are
// not started. Shutdown waits for running jobs to finish. If ctx ends first, it cancels the context of
// every running job, waits for them to return and returns ctx.Err(). A second call waits for the first
// to finish and returns nil.
func (r *Runner) Shutdown(ctx context.Context) error {
	r.mu.Lock()
	if r.stopping {
		r.mu.Unlock()
		<-r.done
		return nil
	}
	r.stopping = true
	r.cond.Broadcast()
	r.mu.Unlock()
	defer close(r.done)

	workersDone := make(chan struct{})
	go func() {
		r.wg.Wait()
		close(workersDone)
	}()

	select {
	case <-workersDone:
		return nil
	case <-ctx.Done():
	}

	r.mu.Lock()
	for a := range r.running {
		a.canceled = true
		a.cancel()
	}
	r.mu.Unlock()
	<-workersDone
	return ctx.Err()
}

// Stop shuts the runner down, waiting up to 30 seconds for running jobs. See Shutdown.
func (r *Runner) Stop() {
	ctx, cancel := context.WithTimeout(context.Background(), stopTimeout)
	defer cancel()
	_ = r.Shutdown(ctx)
}

// Pending returns the jobs that still need to run, in enqueue order. Before Shutdown these are the
// queued jobs. After Shutdown they are the jobs that never started, followed by the jobs that Shutdown
// canceled and that then returned an error.
func (r *Runner) Pending() []Job {
	r.mu.Lock()
	defer r.mu.Unlock()
	entries := append([]entry{}, r.queue...)
	sort.Slice(entries, func(i, j int) bool { return entries[i].seq < entries[j].seq })
	failed := append([]entry{}, r.failed...)
	sort.Slice(failed, func(i, j int) bool { return failed[i].seq < failed[j].seq })
	entries = append(entries, failed...)
	jobs := make([]Job, 0, len(entries))
	for _, e := range entries {
		jobs = append(jobs, e.job)
	}
	return jobs
}
