package jobs

import (
	"context"
	"errors"
	"runtime"
	"sync"
	"testing"
	"time"
)

func TestEnqueueAfterShutdownReturnsErrStopped(t *testing.T) {
	r := NewRunner(1, 10, nil)
	r.Start()
	if err := r.Shutdown(context.Background()); err != nil {
		t.Fatal(err)
	}
	job := Job{Name: "late", Run: func(context.Context) error { return nil }}
	if err := r.Enqueue(job); !errors.Is(err, ErrStopped) {
		t.Fatalf("err = %v, want ErrStopped", err)
	}
	if got := names(r.Pending()); len(got) != 0 {
		t.Fatalf("pending = %v, want none", got)
	}
}

func TestShutdownWaitsForRunningJobs(t *testing.T) {
	r := NewRunner(1, 10, nil)
	r.Start()
	finished := false
	if err := r.Enqueue(Job{Name: "slow", Run: func(context.Context) error {
		time.Sleep(50 * time.Millisecond)
		finished = true
		return nil
	}}); err != nil {
		t.Fatal(err)
	}
	time.Sleep(10 * time.Millisecond) // let the worker pick the job up
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	if err := r.Shutdown(ctx); err != nil {
		t.Fatalf("Shutdown = %v, want nil", err)
	}
	if !finished {
		t.Fatal("Shutdown returned before the running job finished")
	}
	if got := names(r.Pending()); len(got) != 0 {
		t.Fatalf("pending = %v, want none", got)
	}
}

func TestShutdownCancelsRunningJobsWhenContextEnds(t *testing.T) {
	r := NewRunner(1, 10, nil)
	r.Start()
	started := make(chan struct{}, 1)
	var cancelled bool
	if err := r.Enqueue(blocker("running", started, &cancelled)); err != nil {
		t.Fatal(err)
	}
	<-started
	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Millisecond)
	defer cancel()
	if err := r.Shutdown(ctx); !errors.Is(err, context.DeadlineExceeded) {
		t.Fatalf("Shutdown = %v, want context.DeadlineExceeded", err)
	}
	if !cancelled {
		t.Fatal("running job's context was not cancelled")
	}
	if got := names(r.Pending()); !equalNames(got, []string{"running"}) {
		t.Fatalf("pending = %v, want [running]", got)
	}
}

