func TestShutdownWithNoRunningJobsReturnsNilWhenContextIsDone(t *testing.T) {
	// Repeated so that the workers' exit and the expired context race in different orders.
	for i := 0; i < 100; i++ {
		r := NewRunner(2, 10, nil)
		r.Start()
		ctx, cancel := context.WithCancel(context.Background())
		cancel()
		if err := r.Shutdown(ctx); err != nil {
			t.Fatalf("iteration %d: Shutdown = %v, want nil", i, err)
		}
	}
}

func TestCapacityZeroAcceptsJobOnlyWhenWorkerIsIdle(t *testing.T) {
	r := NewRunner(1, 0, nil)
	if err := r.Enqueue(Job{Name: "x", Run: func(context.Context) error { return nil }}); !errors.Is(err, ErrQueueFull) {
		t.Fatalf("not started: err = %v, want ErrQueueFull", err)
	}

	r.Start()
	for { // wait until the worker is waiting for a job
		r.mu.Lock()
		idle := r.idle
		r.mu.Unlock()
		if idle == 1 {
			break
		}
		time.Sleep(time.Millisecond)
	}
	ran := make(chan struct{})
	job := Job{Name: "handoff", Run: func(context.Context) error { close(ran); return nil }}
	if err := r.Enqueue(job); err != nil {
		t.Fatalf("idle worker: Enqueue = %v, want nil", err)
	}
	if err := r.Enqueue(job); !errors.Is(err, ErrQueueFull) {
		t.Fatalf("second Enqueue = %v, want ErrQueueFull", err)
	}
	<-ran
	if err := r.Shutdown(context.Background()); err != nil {
		t.Fatal(err)
	}
}
